import {displayRunOrder} from '../data-model/workspaces.mjs';
import {h,details,field,table,f} from './dom.mjs';
import {commit,setUi} from './state.mjs';
import {lineChart,styleFor} from './charts.mjs';
import {worksheetModel,worksheetSettings} from '../retention/worksheet.mjs';
import {projectR2} from '../retention/fit.mjs';

export function regressionPicture(points,fit,{B=null,logK=null,title='Last-peak fit',id='worksheet-fit-chart'}={}){
 if(!fit?.ok||!points.length)return h('p',{class:'empty'},'The graph appears automatically once at least two valid %B/t0/last-peak points exist. A qualified fit needs at least three distinct %B values.');
 const xs=points.map(p=>p.x),lo=Math.max(0,Math.min(...xs,B??100)-3),hi=Math.min(100,Math.max(...xs,B??0)+3),y=x=>fit.intercept+fit.slope*x;
 const a=Math.min(...xs),b=Math.max(...xs),series=[{id:'observed',label:'Retained last peaks',points:points.map(p=>[p.x,p.y]),kind:'points',color:'#1565c0'},
  {id:'fit',label:'Fitted line within measured %B',points:[[a,y(a)],[b,y(b)]],color:'#1565c0'},
  {id:'extension-low',label:'Extrapolation (verify experimentally)',points:[[lo,y(lo)],[a,y(a)]],dash:'5 4',color:'#8a5a10'},
  {id:'extension-high',label:'Extrapolation (verify experimentally)',points:[[b,y(b)],[hi,y(hi)]],dash:'5 4',color:'#8a5a10'}];
 if(Number.isFinite(logK))series.push({id:'time-limit',label:'Run-time limit',points:[[lo,logK],[hi,logK]],dash:'3 4',color:'#bf2727'});
 const graph=lineChart({series,xLabel:'Solvent B (%B)',yLabel:'log10 K',title:`${title} · R² = ${fit.r2===null?'undefined':f(fit.r2,6)}`,xRange:[lo,hi],markers:Number.isFinite(B)?[{x:B,label:`${B} %B`,color:'#bf2727'}]:[],testid:id});
 return h('figure',{class:'fit-picture'},graph,h('button',{type:'button','data-testid':`enlarge-${id}`,onclick:()=>{const d=h('dialog',{class:'toolkit-zoom','aria-label':'Enlarged retention fit graph'},h('h3',title),h('button',{type:'button',onclick:()=>{d.close();d.remove();}},'Close'),h('div',{class:'toolkit-zoom-scroll'},graph.cloneNode(true)));d.addEventListener('close',()=>d.remove());document.body.append(d);d.showModal();}},'Enlarge fit graph'),h('figcaption',{class:'small'},'Dots: retained-peak data. Blue: fitted range. Dashed amber: extrapolation. Red: run-time boundary / proposed minimum. A good fit does not prove chemical identity.'));
}
export function compoundPictures(r){
 return h('div',{'data-testid':'compound-fit-pictures'},(r.fits?.results||[]).filter(x=>x.fit.ok).map((x,i)=>h('section',h('h4',x.compound.name),regressionPicture(x.points,x.fit,{B:r.issued?.candidates?.minimum?.B,logK:Number.isFinite(r.steps.t0Proposed?.t0)?Math.log10((r.steps.lastPeakSpec.value-r.steps.t0Proposed.t0)/r.steps.t0Proposed.t0):null,title:x.compound.name,id:`compound-fit-chart-${i}`}))));
}
export function worksheetPanel(st){
 const s=st.session,w=st.evaluation.worksheet||worksheetModel(st.session),cfg=worksheetSettings(st.session.settings.worksheet);
 const update=(key,value)=>commit(ss=>{ss.settings.worksheet={...ss.settings.worksheet,[key]:value};});
 const rowUpdate=(id,key,value)=>commit(ss=>{ss.settings.worksheet||={};ss.settings.worksheet.rows||={};ss.settings.worksheet.rows[id]={...ss.settings.worksheet.rows[id],[key]:value};});
 const number=e=>e.target.value.trim()===''?null:Number(e.target.value);
 return h('section',{'data-testid':'worksheet-planning'},h('h3','Automatic last-peak calculation (workbook method)'),
  h('p',{class:'small'},'Uses the last retained peak of each non-blank Retention run. Filtering, method corrections and t0 changes recalculate the line, R², graph and minimum automatically. It does not require assigning every compound. The last peak must still be the same compound across the fitted runs.'),
  w.groups.length>1?field('Comparable method group',h('select',{'data-testid':'worksheet-group',onchange:e=>update('groupKey',e.target.value)},w.groups.map(g=>h('option',{value:g.key,selected:w.groupKey===g.key?'selected':null},`${g.label} (${g.runs.length} runs)`)))):null,
  h('button',{type:'button','data-testid':'worksheet-t0-mode',onclick:()=>setUi(u=>{u.worksheetT0Open=!u.worksheetT0Open;})},st.ui.worksheetT0Open?'Close t0 entry':'Supply / correct documented t0'),
  st.ui.worksheetT0Open?h('div',h('p',{class:'small'},'t0 is the measured hold-up time, in minutes: read a confirmed unretained marker (such as uracil) or your recorded workbook value. Do not enter the first visible peak merely because it is first. Use a shared value only if the experimental record supports the same t0; otherwise use per-run corrections.'),h('div',{class:'row wrap'},field('Shared documented t0 (min)',h('input',{type:'number',min:0,step:'any',value:cfg.sharedT0??'','data-testid':'worksheet-t0',onchange:e=>update('sharedT0',number(e))})),field('t0 source / record',h('input',{value:cfg.t0Basis||'','data-testid':'worksheet-t0-basis',placeholder:'Measured uracil / documented workbook value',onchange:e=>update('t0Basis',e.target.value)})))):null,
  h('p',{class:'small'},'If no measured or entered t0 exists, the graph uses a labelled column-volume estimate as a preview. Filtering out a known marker never silently selects a replacement marker. An estimated t0 cannot qualify this handoff.'),
  w.fit?.ok?h('div',{'data-testid':'worksheet-result'},h('p',`log10 K = ${f(w.fit.intercept,6)} ${w.fit.slope<0?'−':'+'} ${f(Math.abs(w.fit.slope),6)} × %B. R² = ${f(w.fit.r2,6)} → ${f(projectR2(w.fit.r2),3)} (rounded to 3 decimals for the user-confirmed project target ≥ 0.995).`),
   h('p',`Mean t0: ${f(w.meanT0,4)} min. Calculated candidate minimum: ${w.calculation?.B??'not feasible'} %B${w.calculation?.B!==null&&w.calculation?`; predicted latest peak ${f(w.calculation.predictedLast,3)} min`:''}.`),
   h('p',{class:w.qualified?'ok':'warn','data-testid':'worksheet-quality'},w.qualified?'Qualified last-peak model: automatically available on Selectivity.':w.qualityPass?'R² target met. Complete the model-evidence checks below before using the candidate.':'Continue Retention: this line has not met the 0.995 fit target / minimum point requirement.'),
   regressionPicture(w.points,w.fit,{B:w.calculation?.B,logK:w.calculation?.logK}),
   details('Residuals: inspect suspect points before adding experiments',false,table(['Run','%B','Residual (log K)'],displayRunOrder(w.points,s).map(p=>h('tr',h('td',p.label),h('td',p.B),h('td',f(p.y-(w.fit.intercept+w.fit.slope*p.x),6))))))):h('p',{class:'empty','data-testid':'worksheet-quality'},w.reason),
  w.rows.length?details('Calculation data / optional t0 corrections and justified fit exclusions',false,
   h('p',{class:'small'},'Original peak numbers and CSVs are unchanged. A point excluded from regression needs a recorded reason; it is not deleted. Do not exclude valid points simply to make R² pass. Mean t0 includes available t0 values from this group, as in workbook D26.'),
   h('button',{type:'button','data-testid':'worksheet-row-edit-mode',onclick:()=>setUi(u=>{u.worksheetRowEdit=!u.worksheetRowEdit;})},st.ui.worksheetRowEdit?'Return to read-only calculation data':'Edit individual t0 / justified regression exclusions'),
   table(['Run','%B','Last retained peak','t0 (min) / source','log K','Fit point / reason'],displayRunOrder(w.rows,s).map(r=>h('tr',h('td',r.label),h('td',r.B??'not recorded'),h('td',r.lastTR===null?'no retained peak':`${f(r.lastTR,3)} min (original #${r.peakNo})`),h('td',f(r.t0,4),h('div',{class:'tiny'},r.basis),st.ui.worksheetRowEdit?h('div',field('Override t0',h('input',{type:'number',step:'any',min:0,value:cfg.rows?.[r.runId]?.t0??'','data-testid':`worksheet-row-t0-${r.runId}`,onchange:e=>rowUpdate(r.runId,'t0',number(e))})),field('Override source',h('input',{value:cfg.rows?.[r.runId]?.t0Basis||'',onchange:e=>rowUpdate(r.runId,'t0Basis',e.target.value)}))):null),h('td',f(r.logK,5)),h('td',r.included?'Included':r.excluded?'Excluded with reason':r.reasons.join('; '),st.ui.worksheetRowEdit?h('div',h('label',{class:'check'},h('input',{type:'checkbox',checked:cfg.rows?.[r.runId]?.exclude===true,'data-testid':`worksheet-exclude-${r.runId}`,onchange:e=>rowUpdate(r.runId,'exclude',e.target.checked)}),' Exclude from regression'),cfg.rows?.[r.runId]?.exclude?field('Reason (required to exclude)',h('input',{value:cfg.rows?.[r.runId]?.reason||'','data-testid':`worksheet-exclude-reason-${r.runId}`,onchange:e=>rowUpdate(r.runId,'reason',e.target.value)})):null):null))),{'data-testid':'worksheet-data'})):null,
  w.rows.length?h('div',h('p',{class:'small'},'Model evidence: '+(w.review?'Your confirmation matches the current calculation.':'Not confirmed. The software can calculate a line but cannot establish from numbered peaks that the same compound, sample and physical column were used.')),
   h('button',{type:'button','data-testid':'worksheet-review-mode',onclick:()=>setUi(u=>{u.worksheetReviewOpen=!u.worksheetReviewOpen;})},st.ui.worksheetReviewOpen?'Close evidence entry':'Review / confirm from my experimental record'),
   st.ui.worksheetReviewOpen?h('div',h('p',{class:'small'},'Use your sample/batch record, actual column allocation and standards or other evidence for the last-eluting compound. If you do not have that evidence, leave this unconfirmed; exploratory graphs and choices are still available.'),field('Experimental record supporting last-peak continuity and comparable conditions',h('input',{value:cfg.reviewBasis||'','data-testid':'worksheet-review-basis',placeholder:'Sample batch, actual column and evidence that the last peak is the same compound',onchange:e=>update('reviewBasis',e.target.value)})),
   h('label',{class:'check'},h('input',{type:'checkbox',checked:w.review,disabled:!cfg.reviewBasis?.trim(),'data-testid':'worksheet-review',onchange:e=>commit(ss=>{ss.settings.worksheet={...ss.settings.worksheet,confirmedSignature:e.target.checked?worksheetModel(ss).signature:null};})}),' I confirm these fitted points describe the same last-eluting compound, sample and physical column under comparable conditions.')):null,
   h('p',{class:'small','data-testid':'worksheet-blockers'},w.reason),
   h('p',{class:'small'},w.qualified?'Open Selectivity: this fresh calculation appears automatically; Retention CSVs remain here.':w.fit?.ok?'If R² is below 0.995, inspect the residuals and the actual last peak/t0. Repeat a suspect acquisition or add a justified %B point. More points do not guarantee a higher R².':'Supply valid %B, t0 and retained peaks to fit a line.')):null);
}
